
from typing import List

class Solution:
    def maximumSaleItems(self, items: List[List[int]], budget: int) -> int:
        n = len(items)

        # Calculate free copies generated by purchasing each item type
        bonus = [0] * n

        for i in range(n):
            for j in range(n):
                if i != j and items[j][0] % items[i][0] == 0:
                    bonus[i] += 1

        # dp[b] = maximum items obtained using exactly b money
        NEG = float('-inf')
        dp = [NEG] * (budget + 1)
        dp[0] = 0

        for i in range(n):
            price = items[i][1]
            extra = bonus[i]
            ndp = dp[:]

            # Process each remainder independently
            for r in range(min(price, budget + 1)):
                best = NEG
                k = 0

                for b in range(r, budget + 1, price):
                    if b >= price and dp[b - price] != NEG:
                        best = max(best, dp[b - price] - (k - 1))

                    if best != NEG:
                        ndp[b] = max(ndp[b], k + extra + best)

                    k += 1

            dp = ndp

        return max(dp)
